/* QCL professional upgrade: existing visual identity, independent assessment and adaptive practice. */
'use strict';

const ASSET='assets/images/';
const $=id=>document.getElementById(id);
const escapeHTML=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const stage=$('stage');
const steps=['intro','excerpt','scorecard','coaching-prep','decision1','decision2','recovery','rehearse-answer','rehearse-close','reflection','assessment','results','finish'];
function routeSteps(){return practice.d2Submitted&&!recoveryData()?steps.filter(k=>k!=='recovery'):steps;}
const chapterNames={intro:'WELCOME',review:'SCENE 01 · OBSERVE',excerpt:'SCENE 01 · CALL EVIDENCE',scorecard:'SCENE 01 · QUALITY REVIEW',observation:'SCENE 01 · PRACTICE','coaching-prep':'SCENE 02 · PREPARE','prep-barrier':'SCENE 02 · PREPARE','prep-goal':'SCENE 02 · PREPARE','prep-summary':'SCENE 02 · PREPARE',decision1:'SCENE 02 · COACH',concern:'SCENE 02 · COACH',decision2:'SCENE 02 · COACH',recovery:'SCENE 02 · CONVERSATION OUTCOME','rehearse-answer':'SCENE 02 · REHEARSE','rehearse-close':'SCENE 02 · REHEARSE','rehearse-summary':'SCENE 02 · REHEARSAL SUMMARY',reflection:'SCENE 03 · REFLECT','assessment-intro':'SCENE 04 · ASSESS',assessment:'SCENE 04 · ASSESS',results:'SCENE 04 · RESULTS',finish:'COMPLETE'};
let step='intro';
let practice={};
let reflection='';
let planChoices={};let planReviewed=false;
let answers=[null,null,null];
let assessmentIndex=0;
let submitted=[false,false,false];
let assessmentReview=false;
let attemptNumber=1;
let completedAttempt=null;
let ASSESSMENT_QUESTIONS=ASSESSMENT_BANK[0];
const CALL_LINES=[["Representative","I’ve updated your mailing address. The change is saved, and future statements will go to the new address."],["Customer","Okay. Does that include the statement that’s coming out this week?"],["Representative","Your address is updated in the system. Thanks for calling, and have a great day!"]];
let evidence=[]; let evidenceSubmitted=false;
let qualityRatings={}; let qualitySubmitted=false;
let prepChoices={}; let prepSubmitted={};
const QUALITY_STATES={met:'Met',not:'Not met',unknown:'Insufficient evidence'};
const QUALITY_CRITERIA=[
 {id:'update',title:'Confirmed that the address update was saved',correct:'met',why:'The Representative explicitly confirmed that the change was saved. This establishes what was communicated, not independent proof of the system update.'},
 {id:'followup',title:'Answered the customer’s follow-up question',correct:'not',why:'The customer asked about this week’s statement, but the Representative repeated the address update.'},
 {id:'understanding',title:'Checked customer understanding before closing',correct:'not',why:'No understanding check occurred in this excerpt.'},
 {id:'closing',title:'Closed the conversation courteously',correct:'met',why:'The Representative thanked the customer and offered a courteous closing.'},
 {id:'processing',title:'Verified system status: whether this week’s statement will use the new address',correct:'unknown',why:'The actual processing status is not established in the excerpt. The reviewer cannot verify the statement’s destination from the dialogue alone.'}
];
const PREPARATION={
 'coaching-prep':{title:'Identify the Evidence',prompt:'Which observation should guide your coaching?',choices:{A:'The Representative did not care about the customer’s question.',B:'The Representative confirmed the address update but did not answer the follow-up question.',C:'The Representative needs to improve every part of the call.'},correct:'B',feedback:{A:'This assigns an intention without supporting evidence.',B:'This identifies a specific, observable behavior.',C:'The call also contained strengths. Focus on the specific performance gap.'}},
 'prep-barrier':{title:'Explore Possible Barriers',prompt:'What should you establish before recommending a solution?',choices:{A:'Whether the Representative had reliable information about statement processing.',B:'Whether the Representative should receive a lower performance rating.',C:'Whether the Representative can complete calls more quickly.'},correct:'A',feedback:{A:'The issue could involve knowledge, unclear guidance or access to information.',B:'A score alone does not explain why the behavior occurred.',C:'Efficiency may matter, but it does not establish the cause of this issue.'}},
 'prep-goal':{title:'Set the Coaching Goal',prompt:'Which goal best addresses the quality finding?',choices:{A:'Improve customer service.',B:'Reduce call handling time.',C:'Answer follow-up questions directly or explain how the information will be verified before closing.'},correct:'C',feedback:{A:'This goal is too broad to observe reliably.',B:'This does not directly address the identified communication gap.',C:'This is specific, observable and connected to the call evidence.'}}
};
const PREP_ORDER=Object.keys(PREPARATION);
const qualityComplete=()=>QUALITY_CRITERIA.every(c=>Object.hasOwn(QUALITY_STATES,qualityRatings[c.id]));
const qualityScore=()=>QUALITY_CRITERIA.filter(c=>qualityRatings[c.id]===c.correct).length;
const prepScore=()=>PREP_ORDER.filter(k=>prepSubmitted[k]&&prepChoices[k]===PREPARATION[k].correct).length;


const PRACTICE_OBSERVATION={
 prompt:'Based on the call excerpt, which observation is supported by the evidence?',
 choices:{
  A:'The Representative gave incorrect information about when the new address would be used.',
  B:'The Representative confirmed the address update but did not directly answer the question about this week’s statement.',
  C:'The Representative ended the call quickly because she wanted to avoid a longer conversation.'
 },correct:'B',
 feedback:{
  A:'The excerpt confirms the address was changed, but it does not establish that the details provided were incorrect. Look at the specific follow-up question the customer asked.',
  B:'Correct. The customer asked whether the update applied to the statement coming out this week. The Representative repeated that the address was updated without directly addressing that question.',
  C:'The call shows that the question was not answered. It does not show why the Representative ended the call, so avoid assigning motives.'
 }
};
const DECISION1={
 prompt:"You've reviewed the call and noticed an opportunity to respond more directly to a customer follow-up. How would you start the coaching conversation?",
 choices:{
  A:"You confirmed the address update clearly. Could we look together at how the customer's question about this week's statement was handled?",
  B:"You confirmed the address update, but you didn't answer the customer's question. Next time, make sure you give the right response before ending the call.",
  C:"You ended the call after repeating the update. Were you trying to avoid a longer conversation?"
 },correct:'A',
 reactions:{
  A:"I hadn't realized the customer's question about this week's statement was still unanswered. I'd like to review it together and practice a better response.",
  B:"Okay, I understand. I'll try to answer those follow-up questions more directly.",
  C:"No, I wasn't trying to end the call quickly. I thought I had answered the customer's question."
 },
 feedback:{
  A:"This collaborative opening acknowledges what the Representative did well, identifies an observable gap, and invites reflection without assigning intent.",
  B:"This identifies the gap, but jumps to the correction before inviting the Representative to reflect on the call evidence.",
  C:"This assumes a reason for the behavior that the call does not establish. Begin with the customer's unanswered question instead."
 }
};
const BRANCHES={
 A:{quote:"I can see the unanswered question now. I worry that asking more questions will make my calls longer. How can I balance that?",title:'Build on the collaboration',prompt:'How would you help the Representative turn her insight into a workable behavior?',choices:{A:'Set a mandatory long checklist for every call.',B:'Acknowledge the concern and practice one brief understanding check where it fits naturally.',C:'Suggest checking only when the customer sounds confused.'},correct:'B',feedback:{A:'A fixed checklist can create unnecessary steps. Collaborate on a brief, purposeful check.',B:'You preserve the collaborative tone and help her rehearse a realistic behavior.',C:'Confusion is not always audible. A purposeful check helps uncover gaps.'}},
 B:{quote:"I’ll try to answer more directly, but I’m not sure what I should say if I don’t know whether the statement has already gone out.",title:'Invite reflection before correcting',prompt:'How would you help her move from compliance to understanding?',choices:{A:'Ask what she noticed, locate the approved guidance together, and practice a clear verification response.',B:'Repeat the instruction to answer correctly without discussing the uncertainty.',C:'Tell her to make an educated guess so the call stays short.'},correct:'A',feedback:{A:'You turn a directive opening into joint problem-solving and reinforce accurate information.',B:'Repeating the instruction does not resolve the source of uncertainty.',C:'Guessing can mislead the customer. Verify using approved guidance.'}},
 C:{quote:"I wasn’t trying to rush the call. I thought I had answered the question, and I feel like you’re assuming the worst.",title:'Repair the coaching relationship',prompt:'How would you respond to the Representative’s concern about your opening?',choices:{A:'Defend your original interpretation and move on to the correction.',B:'Drop the coaching conversation to avoid conflict.',C:'Acknowledge the assumption, return to the observable question, and invite her perspective before practicing a response.'},correct:'C',feedback:{A:'Defending an assumption can make it harder to discuss the evidence.',B:'Avoiding the issue misses a chance to support the employee and customer.',C:'You repair the opening, restore a shared focus on evidence and invite collaboration.'}}
};
const activeBranch=()=>BRANCHES[practice.d1||'A'];
const isCorrect=(q,choice)=>!!q&&Object.hasOwn(q.ids,choice)&&q.ids[choice]===q.correctId;
// Lesson 02A: descriptive, fictional conversation states; no numeric employee ratings.
const OPENING_IMPACT={A:['Supportive','Specific evidence','Engaged'],B:['Developing','Correction given','Needs invitation'],C:['Needs repair','Assumption made','Guarded']};
const OUTCOMES={
 AA:{expression:'uncertain',dialogue:'I can follow a checklist, but I’m worried it will add steps even when the customer has no more questions.',impact:['Supportive','Overly prescriptive','Needs tailoring'],gap:'The checklist is not tailored to the actual customer question.',repair:'You’re right that not every call needs extra steps. Let’s rehearse one brief check when a customer asks a follow-up.',wrong:['Keep every step mandatory so expectations are consistent.','Ask her to skip all understanding checks.'],correct:'B',resolved:'A brief, relevant check feels much more realistic.'},
 AB:{expression:'understanding',dialogue:'A short check makes sense. I can answer the specific question and confirm we’re clear without repeating everything.',impact:['Supportive','Clear next step','Engaged'],gap:'The learner connected the concern about time to purposeful practice.'},
 AC:{expression:'uncertain',dialogue:'Some customers sound confident even when they still have questions. How would I know when to check?',impact:['Supportive','Needs clarification','Needs guidance'],gap:'Relying only on tone can miss an unanswered question.',repair:'Use the customer’s actual question as the cue; answer or verify it, then briefly check understanding.',wrong:['Trust your first impression of the customer’s tone.','Ask a long set of questions on every call.'],correct:'C',resolved:'I can use the question itself rather than guessing from tone.'},
 BA:{expression:'understanding',dialogue:'That helps. If I’m unsure, I can find the current guidance with you and practice explaining the verification step.',impact:['Supportive','Clear next step','Engaged'],gap:'Joint problem-solving addressed the information barrier.'},
 BB:{expression:'uncertain',dialogue:'I understand the instruction, but I still don’t know where to find the right statement-processing information.',impact:['Developing','Barrier unresolved','Needs invitation'],gap:'Repeating the correction did not resolve access to guidance.',repair:'Let’s find the approved source together and practice what to say if the status is unclear.',wrong:['Ask her to remember the instruction and move on.','Set a faster call-time target.'],correct:'A',resolved:'Now I know what to check and how to explain the next step.'},
 BC:{expression:'concerned',dialogue:'I’m uncomfortable guessing about the statement. What if I give the customer incorrect information?',impact:['Developing','Accuracy at risk','Needs support'],gap:'Guessing could mislead the customer.',repair:'You’re right to avoid guessing. Use the approved source or explain the verification step before closing.',wrong:['Give the most likely answer to save time.','Avoid discussing the customer’s question.'],correct:'B',resolved:'I can be clear about what I know and what needs verification.'},
 CA:{expression:'concerned',dialogue:'I still feel that my intention is being judged. It’s difficult to discuss the call when we haven’t cleared that up.',impact:['Needs repair','Assumption persists','Guarded'],gap:'Defending the assumption leaves the relationship barrier unresolved.',repair:'I made an assumption about your intention. Let’s return to the customer’s question and hear your perspective.',wrong:['Explain again why your interpretation was correct.','Change the subject to the next quality score.'],correct:'C',resolved:'Thank you for acknowledging that. I’m ready to look at the call together.'},
 CB:{expression:'concerned',dialogue:'We can move on, but I still don’t know what to do differently when a customer asks that kind of question.',impact:['Needs repair','No next step','Disengaged'],gap:'Avoiding the conversation leaves the performance gap unaddressed.',repair:'I want to revisit the evidence respectfully. What made the question difficult, and what could we verify together?',wrong:['Leave the issue unaddressed.','Send a correction without discussing the evidence.'],correct:'A',resolved:'I’m willing to revisit the call and work on a specific response.'},
 CC:{expression:'understanding',dialogue:'I appreciate you coming back to the evidence. I’m ready to discuss what happened and practice a different response.',impact:['Repaired','Clear next step','Re-engaged'],gap:'Acknowledging the assumption restored a shared focus on the evidence.'}
};
function initialOutcome(){return OUTCOMES[(practice.d1||'A')+(practice.d2||'B')]||OUTCOMES.AB;}
function recoveryData(){const o=initialOutcome();if(!o.repair)return null;let w=0;return {prompt:'Which response would address the remaining barrier?',choices:Object.fromEntries([..."ABC"].map(k=>[k,k===o.correct?o.repair:o.wrong[w++]])),correct:o.correct};}
function branchOutcome(){const o=initialOutcome();if(o.repair&&practice.recoverySubmitted&&practice.recovery===o.correct)return {...o,expression:'understanding',dialogue:o.resolved,impact:[practice.d1==='C'?'Repaired':'Supportive','Clear next step','Re-engaged'],gap:'The learner addressed the remaining barrier and invited a practical next step.'};return o;}
function impactPanel(values){return `<section class="impact-panel" aria-label="Illustrative conversation impact"><h2 class="section-heading">Conversation impact</h2><p class="impact-caption">These fictional reactions describe the conversation; they are not measured employee scores.</p><dl class="impact-grid">${['Rapport','Clarity','Collaboration'].map((k,i)=>`<div class="mini-card"><dt>${k}</dt><dd>${escapeHTML(values[i])}</dd></div>`).join('')}</dl></section>`;}
function renderRecovery(){const o=initialOutcome(),q=recoveryData(),answered=practice.recoverySubmitted,chosen=practice.recovery,success=answered&&chosen===q?.correct;const final=branchOutcome();return `<div class="scene-card">${intro('SCENE 02 · CONVERSATION OUTCOME',success?'Conversation Repaired':q?'Repair the Conversation':'Build on Your Progress',success?'Your recovery response addressed the remaining barrier. Review the updated conversation impact.':q?'Your last response left a barrier unresolved. Try a targeted recovery response.':'Your response addressed the concern. Review how the conversation has developed.')}${representativeReaction(final.expression,final.dialogue)}${impactPanel(final.impact)}<div class="evidence-note"><strong>What happened:</strong> ${escapeHTML(final.gap)}</div>${q?quizOptions(q,'recovery',chosen,answered):''}${answered?infoBox('RECOVERY FEEDBACK',success?'A constructive repair':'The barrier remains',success?'Your response addresses the specific concern and establishes a workable next step.':o.gap+' Consider the response that directly addresses this barrier.','Return to the observable evidence and agree on a realistic next step.',success):''}<div class="btn-row split">${button('← Coaching response','back','btn btn-secondary')}${q&&!answered?`<button type="button" class="btn" data-action="submit-recovery" ${!chosen?'disabled':''}>Submit recovery response</button>`:button('Next: Rehearse the customer response')}${q&&answered&&!success?button('Try another recovery response','retry-recovery','btn btn-secondary'):''}</div>${button('Replay coaching from the opening','replay-coaching','btn btn-secondary')}</div>`;}
// Character 02 approved expression portraits: A/B/C reactions stay separate from scoring.
// These are displayed as real HTML beside the existing feedback, never baked into slide art.
const REACTION_IMAGES={
  understanding:'QCL_CHAR02_Reaction_Understanding.webp',
  uncertain:'QCL_CHAR02_Reaction_Uncertain.webp',
  concerned:'QCL_CHAR02_Reaction_Concerned_Defensive.webp'
};
const REACTION_DESCRIPTIONS={
  understanding:'The blonde Representative listens with an understanding expression.',
  uncertain:'The blonde Representative looks thoughtful and uncertain.',
  concerned:'The blonde Representative appears concerned and defensive.'
};
function representativeReaction(expression,dialogue='',label='REPRESENTATIVE REACTION'){
  const filename=REACTION_IMAGES[expression];
  if(!filename)return '';
  // The portrait is illustrative; all approved feedback remains accessible, live HTML.
  const speech=dialogue?`<p>“${escapeHTML(dialogue)}”</p>`:'';
  return `<div class="scene-banner reaction-panel" aria-label="${escapeHTML(label)}">
    <img src="${ASSET+filename}" alt="${escapeHTML(REACTION_DESCRIPTIONS[expression])}" loading="lazy" width="180" height="200">
    <div><span class="eyebrow">${escapeHTML(label)}</span>${speech}</div>
  </div>`;
}
// Illustrative assessment reactions, not fictional dialogue attributed to the scenario.
function assessmentFeedbackReaction(index,choice){
 const q=ASSESSMENT_QUESTIONS[index];return representativeReaction(isCorrect(q,choice)?'understanding':'uncertain','',`ILLUSTRATIVE RESPONSE · OPTION ${choice}`);
}
const IMAGE_SIZES={"QCL_Avatar_Customer_Q01.webp": [220, 220], "QCL_Avatar_Customer.webp": [220, 220], "QCL_Avatar_Team_Leader.webp": [220, 220], "QCL_Avatar_Representative.webp": [220, 220], "QCL_Avatar_Representative_Q01.webp": [220, 220], "QCL_CHAR02_Reaction_Uncertain.webp": [360, 540], "QCL_S01_01_QA_Review.webp": [1410, 755], "QCL_Opening_Image.webp": [1440, 810], "QCL_CHAR02_Reaction_Concerned_Defensive.webp": [360, 540], "QCL_S02_02_Coaching_Office.webp": [1104, 708], "QCL_S02_10_Representative_Concern.webp": [1440, 810], "QCL_CHAR02_Reaction_Understanding.webp": [360, 540], "QCL_S04_Completion_Characters01_02_Celebrating.webp": [1440, 1040]};
function img(name,alt,css='wide-photo'){const [w,h]=IMAGE_SIZES[name]||[1440,810];return `<img class="${css}" src="${ASSET+name}" width="${w}" height="${h}" alt="${escapeHTML(alt)}">`;}

// Assessment avatars use approved existing illustrated portraits and the same QCL art palette.
// The portraits decorate live HTML dialogue; they do not contain any functional buttons.
const ASSESSMENT_AVATARS={
  Representative:'assets/avatars/QCL_Avatar_Representative.webp',
  Customer:'assets/avatars/QCL_Avatar_Customer.webp',
  'Team Leader':'assets/avatars/QCL_Avatar_Team_Leader.webp'
};
const QUESTION_ONE_AVATARS={
  Representative:'assets/avatars/QCL_Avatar_Representative_Q01.webp',
  Customer:'assets/avatars/QCL_Avatar_Customer_Q01.webp'
};
function speakerPortrait(role,extra='',questionIndex=null){
  const path=questionIndex===0?(QUESTION_ONE_AVATARS[role]||ASSESSMENT_AVATARS[role]):ASSESSMENT_AVATARS[role];
  return path?`<img class="assessment-avatar ${extra}" src="${path}" alt="" loading="lazy" width="78" height="78">`:'';
}
function assessmentCast(index){
  const roles=index===1?['Team Leader','Representative']:['Representative','Customer'];
  const context=index===1?'Coaching conversation':'Customer interaction';
  return `<div class="assessment-cast" aria-label="${context} participants"><p class="cast-caption">${context}</p><div class="cast-people">${roles.map(role=>`<div class="cast-person">${speakerPortrait(role,'',index)}<span>${escapeHTML(role)}</span></div>`).join('')}</div></div>`;
}
function assessmentCastIntroduction(){
  return `<div class="assessment-character-intro"><h2 class="section-heading">Meet the people in the scenarios</h2><div class="assessment-character-grid">${['Team Leader','Representative','Customer'].map(role=>`<div class="assessment-character">${speakerPortrait(role)}<strong>${escapeHTML(role)}</strong></div>`).join('')}</div></div>`;
}

function button(text,action='next',style='btn'){return `<button type="button" class="${style}" data-action="${action}">${text}${action==='back'?'':'<span aria-hidden="true">→</span>'}</button>`;}
function intro(eyebrow,title,description){return `<div class="chapter-intro"><p class="eyebrow">${eyebrow}</p><h1 id="screen-title">${title}</h1>${description?`<p class="lead">${description}</p>`:''}</div>`;}
function nav(nextLabel='Continue',back=true){return `<div class="btn-row ${back?'split':''}">${back?button('← Previous','back','btn btn-secondary'):''}<div class="next-control"><span class="next-context">UP NEXT: ${escapeHTML(nextLabel)}</span>${button('Next')}</div></div>`;}
function mediaCard(file,alt,caption=''){return `<figure style="margin:0">${img(file,alt)}${caption?`<figcaption class="photo-caption">${caption}</figcaption>`:''}</figure>`;}
function transcript(lines,withAvatars=false,questionIndex=null){return `<div class="speaker-lines ${withAvatars?'speaker-lines-illustrated':''}" aria-label="Call transcript">${lines.map(([who,words])=>`<div class="speaker ${who==='Customer'?'customer':''} ${withAvatars?'speaker-illustrated':''}">${withAvatars?speakerPortrait(who,'',questionIndex):''}<div class="speaker-content"><span class="who">${who.toUpperCase()}</span><p>${escapeHTML(words)}</p></div></div>`).join('')}</div>`;}
function quizOptions(data,group,selected,disabled=false){return `<fieldset><legend>${escapeHTML(data.prompt)}</legend><div class="options">${Object.entries(data.choices||data.options).map(([id,text])=>`<label class="option"><input type="radio" name="${group}" value="${id}" aria-label="${escapeHTML(id+'. '+text)}" ${selected===id?'checked':''} ${disabled?'disabled':''}><span aria-hidden="true" class="letter">${id}</span><span class="option-body">${escapeHTML(text)}</span></label>`).join('')}</div></fieldset>`;}
function infoBox(label,heading,body,takeaway,good){return `<div class="feedback ${good?'':'try'}" tabindex="-1" role="region" aria-label="Answer feedback"><div class="feedback-label">${escapeHTML(label)}</div><h2 class="feedback-heading">${escapeHTML(heading)}</h2><p>${escapeHTML(body)}</p>${takeaway?`<div class="takeaway"><strong>Coaching takeaway:</strong> ${escapeHTML(takeaway)}</div>`:''}</div>`;}
function renderIntro(){return `<div class="scene-card intro-coaching-opening"><div class="intro-heading"><p class="eyebrow">AN INTERACTIVE COACHING SIMULATION</p><h1 id="screen-title">Every Conversation Is a Coaching Opportunity</h1><p>You are a contact center Team Leader. Review a call, identify an evidence-based coaching opportunity, guide a supportive conversation, and apply your skills to new situations.</p></div><figure class="opening-scene"><img src="assets/images/QCL_Opening_Image.webp" width="1920" height="1080" alt="A team leader with voluminous dark brown curls, olive cat-eye glasses, and an olive blouse has an encouraging conversation with a blonde Representative wearing a black vest and bubble ponytail. They sit in a warm office with a laptop, notebook, and pink mug."></figure><div class="opening-actions"><div class="assessment-badges"><span>4 stages</span><span>Self-paced · 14–15 screens</span><span>3/3 to pass</span></div><div class="mission-panel"><h2>Your mission</h2><p>Identify observable evidence, choose a supportive coaching opening, adapt to the Representative’s response, and agree on a practical next step. Practice is unscored; the final assessment has three questions and unlimited retries.</p></div>${pendingSave?'':button('Begin experience')}</div></div>`;}
function renderReview(){return `<div class="scene-card">${intro('SCENE 01 · CALL QUALITY REVIEW','Look Beyond the Score','As the Team Leader, review the customer conversation and examine the call evidence yourself.')}${mediaCard('QCL_S01_01_QA_Review.webp','Character 01, the Team Leader with dark chestnut curls and olive cat-eye glasses, reviewing a Call Quality Review dashboard on a laptop at a round wooden table in a warm office.')}<div class="evidence-note">Your task: identify what the Representative actually did, rather than guessing why they did it.</div>${nav('Review the call excerpt')}</div>`;}
function renderExcerpt(){return `<div class="scene-card">${intro('SCENE 01 · CALL EVIDENCE','Find the Call Evidence','Read the conversation and select the two statements that together establish the unanswered customer question. This practice is unscored.')}<div class="quality-layout"><section aria-labelledby="call-context"><h2 id="call-context" class="section-heading">Review the customer interaction</h2>${transcript(CALL_LINES,true)}<p class="transcript-reference"><a href="call-transcript.html" target="_blank" rel="noopener">Open plain-text call transcript (new tab)</a></p></section><section aria-label="Select call evidence"><fieldset class="evidence-field"><legend>Choose two statements</legend>${CALL_LINES.map(([who,words],i)=>`<label class="speaker speaker-illustrated evidence-choice ${who==='Customer'?'customer':''}"><input type="checkbox" name="evidence" value="${i}" ${evidence.includes(i)?'checked':''} ${evidenceSubmitted?'disabled':''}>${speakerPortrait(who)}<span class="speaker-content"><span class="who">${who.toUpperCase()}</span><span class="speaker-words">${escapeHTML(words)}</span></span></label>`).join('')}</fieldset></section></div>${evidenceSubmitted?infoBox('EVIDENCE FEEDBACK',evidence.includes(1)&&evidence.includes(2)?'You found the evidence':'Compare the question and the closing','The customer asks whether this week’s statement will be affected. The closing repeats the address change without directly answering that question. Together these statements establish the observable gap.','Coach what the evidence supports, not what you assume.',evidence.includes(1)&&evidence.includes(2)):''}<div class="btn-row split">${button('← Previous','back','btn btn-secondary')}${evidenceSubmitted?button('Next: Quality scorecard'):`<button class="btn" type="button" data-action="submit-evidence" ${evidence.length!==2?'disabled':''}>Review my evidence</button>`}</div></div>`;}
function renderObservation(){const answered=practice.observationSubmitted;const choice=practice.observation;return `<div class="scene-card">${intro('SCENE 01 · UNSCORED PRACTICE','Identify the Coaching Opportunity','Select the observation best supported by the call excerpt. This practice question does not affect your final assessment.')}${quizOptions(PRACTICE_OBSERVATION,'obs',choice,answered)}${answered?infoBox('OBSERVATION FEEDBACK',choice==='B'?'Evidence first':'Look for observable evidence',PRACTICE_OBSERVATION.feedback[choice],'Strong observations focus on what happened and how it affected customer understanding.',choice==='B'):''}<div class="btn-row split">${button('← Review transcript','back','btn btn-secondary')}${answered?button('Next: Coaching'):`<button type="button" class="btn" data-action="submit-practice" ${!choice?'disabled':''}>Submit observation <span aria-hidden="true">→</span></button>`}</div></div>`;}
function qualitySummary(){return `<section class="quality-summary" aria-labelledby="quality-summary-title"><h2 id="quality-summary-title" class="section-heading">Reviewed quality findings</h2><p>Use the corrected practice rubric, not unverified ratings, to prepare for coaching.</p><ul class="quality-findings">${QUALITY_CRITERIA.map(c=>`<li><span class="quality-status status-${c.correct}">${QUALITY_STATES[c.correct]}</span><span>${escapeHTML(c.title)}</span></li>`).join('')}</ul><div class="evidence-note"><strong>Primary coaching opportunity:</strong> Address the customer’s specific unanswered question or explain how to verify the answer before closing.</div></section>`;}
function renderScorecard(){return `<div class="scene-card">${intro('SCENE 01 · QUALITY REVIEW','Evaluate the Call','Use the transcript to rate all five criteria. This fictional practice rubric does not count toward the final assessment.')}<details class="transcript-disclosure"><summary>Review the call transcript (optional)</summary>${transcript(CALL_LINES,true)}<p class="transcript-reference"><a href="call-transcript.html" target="_blank" rel="noopener">Open plain-text call transcript (new tab)</a></p></details><section aria-labelledby="scorecard-heading"><h2 id="scorecard-heading" class="section-heading">Quality review scorecard</h2><p>Rate each behavior, then submit your review. Open the transcript above whenever you need to refer to the conversation.</p><div class="evidence-note">Met = observed; Not met = expected behavior missed; Insufficient evidence = cannot establish the finding from the excerpt.</div>${QUALITY_CRITERIA.map((c,i)=>`<fieldset class="quality-criterion" ${qualitySubmitted?'disabled':''}><legend>${i+1}. ${escapeHTML(c.title)}</legend><div class="quality-options">${Object.entries(QUALITY_STATES).map(([id,label])=>`<label class="quality-option"><input type="radio" name="quality-${c.id}" value="${id}" ${qualityRatings[c.id]===id?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`).join('')}</section>${qualitySubmitted?`<section class="feedback ${qualityScore()===5?'':'try'}" tabindex="-1" aria-label="Quality review feedback"><h2 class="feedback-heading">${qualityScore()}/5 accurate observations</h2><p>Compare your ratings with the evidence-based findings.</p><div class="quality-results">${QUALITY_CRITERIA.map(c=>`<article class="quality-result"><h3>${escapeHTML(c.title)}</h3><p><strong>${qualityRatings[c.id]===c.correct?'✓ Accurate observation':'Review this observation'}</strong> · Your rating: ${QUALITY_STATES[qualityRatings[c.id]]} · Expected: ${QUALITY_STATES[c.correct]}</p><p>${escapeHTML(c.why)}</p></article>`).join('')}</div><div class="takeaway"><strong>Primary coaching opportunity:</strong> The customer’s follow-up question was not answered. Avoid assigning intent.</div></section>`:''}<div class="btn-row split">${button('← Previous','back','btn btn-secondary')}${qualitySubmitted?button('Try scorecard again','retry-quality','btn btn-secondary')+button('Next: Prepare for coaching'):`<button class="btn" type="button" data-action="submit-quality" ${qualityComplete()&&evidenceSubmitted?'':'disabled'}>Submit quality review</button>`}</div></div>`;}
function renderPrep(){const q=PREPARATION[step];const i=PREP_ORDER.indexOf(step);const chosen=prepChoices[step];const done=prepSubmitted[step];return `<div class="scene-card">${intro('SCENE 02 · COACHING PREPARATION',q.title,'Prepare before coaching. Practice is unscored; use the reviewed quality findings.')}<div class="assessment-progress"><span>PREPARATION ${i+1} OF 3</span><span class="pill">${['Evidence','Explore','Goal'][i]}</span></div>${i===0?mediaCard('QCL_S02_02_Coaching_Office.webp','The Team Leader and Representative sit across a round wooden table in the approved office setting.')+qualitySummary():''}${quizOptions(q,'prep-choice',chosen,done)}${done?infoBox('PREPARATION FEEDBACK',chosen===q.correct?'Effective preparation':'Consider another approach',q.feedback[chosen],q.choices[q.correct],chosen===q.correct):''}<div class="btn-row split">${button('← Previous','back','btn btn-secondary')}${done?button(i===2?'Review preparation':'Continue'):`<button class="btn" type="button" data-action="submit-prep" ${chosen?'':'disabled'}>Submit answer <span aria-hidden="true">→</span></button>`}</div></div>`;}
function renderPrepSummary(){return `<div class="scene-card">${intro('SCENE 02 · COACHING PREPARATION','Your Coaching Preparation','Carry these reviewed findings into the conversation. Your practice decisions do not affect assessment scoring.')}<div class="evidence-note"><strong>${prepScore()}/3 effective preparation decisions.</strong> Review the recommended approach below.</div><div class="three-steps">${PREP_ORDER.map((k,i)=>{const q=PREPARATION[k];return `<div class="mini-card"><b>${['01 · Evidence','02 · Explore','03 · Goal'][i]}</b><p>${escapeHTML(q.choices[q.correct])}</p></div>`}).join('')}</div><div class="btn-row split">${button('← Previous','back','btn btn-secondary')}${button('Replay preparation','retry-prep','btn btn-secondary')}${button('Start coaching')}</div></div>`;}

function renderPrepWorkspace(){const ready=PREP_ORDER.every(k=>Object.hasOwn(PREPARATION[k].choices,prepChoices[k])),done=PREP_ORDER.every(k=>prepSubmitted[k]);return `<div class="scene-card">${intro('SCENE 02 · PREPARE','Prepare Before You Coach','Use the reviewed quality findings to choose an evidence-based observation, explore possible barriers and set an observable coaching goal. Unscored practice.')}${mediaCard('QCL_S02_02_Coaching_Office.webp','The Team Leader and Representative sit across a round wooden table in the approved office.')}${qualitySummary()}<div class="prep-workspace">${PREP_ORDER.map((k,i)=>{const q=PREPARATION[k],chosen=prepChoices[k];return `<section class="prep-section"><h2 class="section-heading">${i+1}. ${escapeHTML(q.title)}</h2>${quizOptions(q,'prep-'+k,chosen,done)}${done?infoBox('PREPARATION FEEDBACK',chosen===q.correct?'Effective preparation':'Consider another approach',q.feedback[chosen],q.choices[q.correct],chosen===q.correct):''}</section>`}).join('')}</div>${done?`<section class="feedback prep-summary" tabindex="-1" aria-label="Preparation summary"><h2 class="feedback-heading">${prepScore()}/3 effective preparation decisions</h2><div class="three-steps">${PREP_ORDER.map((k,i)=>`<div class="mini-card"><b>${['Evidence','Explore','Goal'][i]}</b><p>${escapeHTML(PREPARATION[k].choices[PREPARATION[k].correct])}</p></div>`).join('')}</div></section>`:''}<div class="btn-row split">${button('← Quality review','back','btn btn-secondary')}${done?button('Replay preparation','retry-prep','btn btn-secondary')+button('Start coaching'):`<button class="btn" data-action="submit-prep-all" ${ready?'':'disabled'}>Review preparation →</button>`}</div></div>`;}
function renderDecision1(){const answered=practice.d1Submitted;const choice=practice.d1;const reactionExpression=choice==='A'?'understanding':choice==='B'?'uncertain':'concerned';return `<div class="scene-card">${intro('SCENE 02 · COACHING DECISION 01','How Would You Start?','Your first response shapes the tone of the entire coaching conversation.')}<div class="evidence-note"><strong>Your reviewed preparation:</strong> Focus on the unanswered question, explore whether reliable guidance was available, and agree on an observable verification or response behavior.</div>${quizOptions(DECISION1,'d1',choice,answered)}${answered?`${representativeReaction(reactionExpression,DECISION1.reactions[choice])}${impactPanel(OPENING_IMPACT[choice])}${infoBox('COACHING FEEDBACK',choice==='A'?'A collaborative start':'Consider the opening',DECISION1.feedback[choice],'Begin with evidence, invite dialogue, and avoid assigning intentions.',choice==='A')}`:''}<div class="btn-row split">${button('← Preparation','back','btn btn-secondary')}${answered?button('Next: Continue Conversation'):`<button type="button" class="btn" data-action="submit-practice" ${!choice?'disabled':''}>Submit response <span aria-hidden="true">→</span></button>`}</div></div>`;}
function renderConcern(){const b=activeBranch();return `<div class="scene-card">${intro('SCENE 02 · REPRESENTATIVE RESPONSE','Listen Before You Respond','The Representative’s response depends on how you opened the conversation.')}${mediaCard('QCL_S02_10_Representative_Concern.webp','The Team Leader listens to the Representative at the round wooden table.')}<blockquote class="quote">“${escapeHTML(b.quote)}”</blockquote>${nav('Choose your response')}</div>`;}
function renderDecision2(){const b=activeBranch();const answered=practice.d2Submitted;const choice=practice.d2;const reaction=initialOutcome();return `<div class="scene-card">${intro('SCENE 02 · ADAPT YOUR COACHING',b.title,'Respond to the situation you created in Decision 01.')}${mediaCard('QCL_S02_10_Representative_Concern.webp','Team Leader listening to the Representative during coaching.')}<p class="eyebrow dialogue-label">REPRESENTATIVE</p><blockquote class="quote">“${escapeHTML(b.quote)}”</blockquote>${quizOptions(b,'d2',choice,answered)}${answered?`${representativeReaction(reaction.expression,reaction.dialogue)}${impactPanel(reaction.impact)}${infoBox('COACHING CONSEQUENCE',choice===b.correct?'A constructive next step':'Opportunity to improve',b.feedback[choice],'Agree on a specific behavior, practice it, and review future evidence.',choice===b.correct)}`:''}<div class="btn-row split">${button('← Coaching opening','back','btn btn-secondary')}${answered?button(recoveryData()?'Next: Repair the conversation':'Next: Rehearse the response'):`<button type="button" class="btn" data-action="submit-practice" ${!choice?'disabled':''}>Submit response <span aria-hidden="true">→</span></button>`}</div>${answered&&!recoveryData()?button('Replay coaching from the opening','replay-coaching','btn btn-secondary'):''}</div>`;}
// Lesson 02B: guided rehearsal. This is unscored practice, separate from assessment.
const REHEARSAL={
 'rehearse-answer':{title:'Practice an Improved Customer Response',description:'Coach the Representative through a short rehearsal. Choose what she should say to address the original customer question.',prompt:'Which response should the Representative practice first?',customer:'Does that include the statement that’s coming out this week?',choices:{A:'Your address is updated, so your future statements will go to the new address.',B:'That depends on whether this week’s statement has already been processed. Let me check its status so I can confirm which address it will use.',C:'The change is saved. You can check your next statement online to see whether it was updated.'},correct:'B',feedback:{A:['The question remains unanswered','The address update is confirmed, but the timing of this specific statement remains unclear.','I understand the address changed, but what about this week’s statement?'],B:['A specific, reliable response','This acknowledges the actual question and commits to checking the status before making a promise.','Thank you. I’d appreciate knowing which address it will use.'],C:['The burden shifts to the customer','Online access may be useful, but it does not establish which address this statement will use or offer a direct verification step.','Can you check whether this week’s statement will go to the new address?']},model:'That depends on whether this week’s statement has already been processed. Let me check its status so I can confirm which address it will use.'},
 'rehearse-close':{title:'Confirm Understanding Before Closing',description:'For this fictional rehearsal only, the system now confirms that this week’s statement was already processed for the old address. The new address applies to future statements. Follow approved policy for any delivery or reissue options; no such policy is supplied in this scenario.',prompt:'Which response best explains the verified result and checks understanding?',customer:'So what does that mean for the statement coming this week?',choices:{A:'This week’s statement was processed before the update and is going to the old address. Future statements will use the new address. What questions do you have about those two statements? I can check the available options for this week’s statement.',B:'This week’s statement is going to the old address, and future statements will use the new address. Thank you for calling.',C:'This week’s statement has already been processed. You can update the address again if you need to.'},correct:'A',feedback:{A:['Clear explanation and a useful understanding check','The response distinguishes this week’s statement from future statements, invites questions, and offers to verify options without inventing policy.','I understand the difference now. Could you check what options I have for this week’s statement?'],B:['Accurate, but the closing misses a check','The timing is explained correctly, but the Representative closes without checking understanding or addressing remaining needs.','Okay, but is there anything I can do about the statement going to my old address?'],C:['An unclear next step','Updating an already saved address again does not change a statement that has been processed. Explain the verified result and check available options.','I already updated it. Will doing that again change this week’s statement?']},model:'This week’s statement was processed before the update and is going to the old address. Future statements will use the new address. What questions do you have about those two statements? I can check the available options for this week’s statement.'}
};
const REHEARSAL_ORDER=Object.keys(REHEARSAL);
function rehearsalSummary(){return REHEARSAL_ORDER.map(k=>{const q=REHEARSAL[k];return {key:k,title:q.title,chosen:practice[k],correct:practice[k]===q.correct,model:q.model}});}
function rehearsalFeedback(q,choice){const [heading,body,response]=q.feedback[choice];return `${transcript([['Customer',response]],true)}${infoBox('REHEARSAL FEEDBACK',heading,body,'Model the accurate response, then have the Representative rehearse it in her own words.',choice===q.correct)}<div class="rehearsal-model"><h2 class="section-heading">Model response</h2>${transcript([['Representative',q.model]],true)}</div>`;}
function renderRehearsal(){const q=REHEARSAL[step],choice=practice[step],answered=practice[step+'Submitted'];const first=step===REHEARSAL_ORDER[0];const next=first?'Next: Confirm understanding':'Next: Action plan';return `<div class="scene-card rehearsal-card">${intro('SCENE 02 · REHEARSE',q.title,q.description)}<p class="pill">Practice ${first?1:2} of 2 · Unscored</p>${first?`<div class="evidence-note"><strong>Coaching connection:</strong> ${escapeHTML(branchOutcome().dialogue)} ${branchOutcome().expression==='understanding'?'Build on this outcome by modeling a practical response.':'Acknowledge any remaining barrier before modeling a practical response; the rehearsal does not imply the barrier is resolved.'}</div>`:''}<div class="rehearsal-layout"><section aria-label="Customer roleplay"><h2 class="section-heading">Customer asks</h2>${transcript([['Customer',q.customer]],true)}${first?'':'<p class="image-note">Verified status in this fictional exercise: this week’s statement was processed for the old address.</p>'}</section><section aria-label="Choose the response">${quizOptions(q,'rehearsal-choice',choice,answered)}${answered?rehearsalFeedback(q,choice):''}</section></div><div class="btn-row split">${button('← Previous','back','btn btn-secondary')}${answered?button(next):`<button type="button" class="btn" data-action="submit-rehearsal" ${!choice?'disabled':''}>Submit practice response <span aria-hidden="true">→</span></button>`}</div>${answered&&choice!==q.correct?button('Try another response','retry-rehearsal','btn btn-secondary'):''}${answered&&!first?`<details class="transcript-disclosure"><summary>Review both model responses</summary>${rehearsalSummary().map(x=>`<section><h3>${escapeHTML(x.title)}</h3>${transcript([['Representative',x.model]])}</section>`).join('')}</details><div class="evidence-note"><strong>Transfer to the workplace:</strong> Rehearse in your own words, verify the information and review later calls together.</div>${button('Replay rehearsal','replay-rehearsal','btn btn-secondary')}`:''}</div>`;}
function renderRehearsalSummary(){const items=rehearsalSummary();return `<div class="scene-card">${intro('SCENE 02 · REHEARSAL SUMMARY','Turn Coaching Into Action','Review the model responses and transfer this practice into your next coaching session.')}<div class="assessment-badges"><span>Unscored practice</span><span>${items.filter(x=>x.correct).length}/2 strongest responses selected</span></div>${items.map((x,i)=>`<section class="rehearsal-model"><h2 class="section-heading">${i+1}. ${escapeHTML(x.title)}</h2><p><strong>${x.correct?'Effective response selected':'Model to practice again'}</strong></p>${transcript([['Representative',x.model]],true)}</section>`).join('')}<div class="evidence-note"><strong>Transfer to the workplace:</strong> Ask the Representative to rehearse in her own words. Confirm the policy or system information, listen for a direct answer and understanding check, then review a small sample of later calls together.</div><div class="btn-row split">${button('← Previous','back','btn btn-secondary')}${button('Next: Action plan')}</div>${button('Replay rehearsal','replay-rehearsal','btn btn-secondary')}</div>`;}
function clearRehearsal(){for(const k of REHEARSAL_ORDER){delete practice[k];delete practice[k+'Submitted'];}clearPlan();}

// Lesson 02C: an unscored, evidence-aligned action plan. Two viable options per field.
const PLAN_FIELDS=[
{id:'goal',title:'1. Observable improvement goal',choices:{A:['Improve customer service generally.','Too broad: the desired behavior must be observable.',false],B:['Answer the customer’s specific follow-up question or explain the verification step before closing.','Directly addresses the gap found in the call.',true],C:['Use a reliable source to verify uncertain information, explain the result and check understanding before closing.','Connects the evidence gap with accurate information and customer understanding.',true]}},
{id:'practice',title:'2. Practice activity',choices:{A:['Rehearse the original call together, using approved guidance, then practice a second similar question.','Builds skill through a model and independent application.',true],B:['Send a reminder to improve quality without a practice opportunity.','A reminder alone does not demonstrate that the behavior can be performed.',false],C:['Role-play two unfamiliar follow-up questions and provide specific feedback after each.','Offers varied practice and immediate feedback.',true]}},
{id:'measure',title:'3. Observable success criterion',choices:{A:['Ask whether the Representative feels more confident.','Confidence is useful context, but it does not measure the desired behavior.',false],B:['In three eligible practice or reviewed calls, look for a direct answer or verification step and an understanding check in all three.','A concrete sample and observable behaviors make the criterion reviewable.',true],C:['Review five eligible calls; look for a direct answer or verification step and an understanding check in at least four.','Defines an observable initial target and sample. Adjust to actual workplace standards.',true]}},
{id:'followup',title:'4. Follow-up review',choices:{A:['Agree to review the selected sample together at the next weekly coaching session; discuss barriers and adjust the plan.','Sets a review point, shared responsibility and an adjustment step.',true],B:['Meet in two weeks to review the selected sample and decide whether additional practice or guidance is needed.','Provides a specific review interval and a decision about further support.',true],C:['Wait until the next poor quality score before discussing progress.','Reactive follow-up can miss opportunities to support improvement.',false]}}
];
function planComplete(){return PLAN_FIELDS.every(f=>Object.hasOwn(f.choices,planChoices[f.id]));}
function planReady(){return planReviewed&&planComplete()&&PLAN_FIELDS.every(f=>f.choices[planChoices[f.id]][2]);}
function clearPlan(){planChoices={};planReviewed=false;reflection='';}
function planText(){if(!planReady())return '';return ['QUALITY & CONVERSATIONS LAB','COACHING ACTION PLAN','Fictional practice plan — adapt to actual policies and coaching needs.','', 'Evidence: The customer’s follow-up question about this week’s statement was unanswered. Statement processing status was unknown in the original call.','',...PLAN_FIELDS.flatMap(f=>[f.title,f.choices[planChoices[f.id]][0],'']),...(reflection.trim()?['Optional practice notes',reflection.trim(),'']:[]),'Review actual workplace guidance and agree on the plan with the Representative before applying it.'].join('\n');}
function printablePlan(){if(!planReady())return '';return `<section class="plan-print" aria-label="Personalized coaching plan"><p class="eyebrow">QUALITY &amp; CONVERSATIONS LAB · PERFORMANCE SUPPORT</p><h2>Your Coaching Action Plan</h2><p>Fictional practice plan — adapt to actual policies and coaching needs.</p><p><strong>Evidence:</strong> The customer’s follow-up question about this week’s statement was unanswered. Statement processing status was unknown in the original call.</p><dl>${PLAN_FIELDS.map(f=>`<div><dt>${escapeHTML(f.title)}</dt><dd>${escapeHTML(f.choices[planChoices[f.id]][0])}</dd></div>`).join('')}</dl>${reflection.trim()?`<p><strong>Optional practice notes:</strong> ${escapeHTML(reflection.trim())}</p>`:''}<p>Review actual workplace guidance and agree on the plan with the Representative before applying it.</p></section>`;}
function planButtons(){return `<div class="btn-row plan-export">${button('Print / save as PDF','print-plan','btn btn-secondary')}${button('Download plan (.txt)','download-plan','btn btn-secondary')}</div>`;}
function renderReflection(){return `<div class="scene-card">${intro('SCENE 03 · REFLECT & PLAN','Build Your Coaching Action Plan','Turn your coaching and rehearsal into a specific improvement plan. This activity is unscored; choose one option in each section and review your plan.')}<div class="evidence-note"><strong>Your coaching outcome:</strong> ${escapeHTML(branchOutcome().dialogue)}</div><div class="evidence-note"><strong>Rehearsal takeaway:</strong> ${practice['rehearse-answer']==='B'&&practice['rehearse-close']==='A'?'You selected both strongest responses.':'Review the model responses before applying this skill.'} Answer or verify the specific question, explain the verified result and check understanding.</div><div class="plan-fields">${PLAN_FIELDS.map(f=>`<fieldset class="plan-field"><legend>${escapeHTML(f.title)}</legend><div class="options">${Object.entries(f.choices).map(([id,v])=>`<label class="option"><input type="radio" name="plan-${f.id}" value="${id}" ${planChoices[f.id]===id?'checked':''} ${planReviewed?'disabled':''}><span class="option-body">${escapeHTML(v[0])}</span></label>`).join('')}</div></fieldset>`).join('')}</div><div class="question-card"><label for="reflection-text" class="question-title">Optional practice notes</label><textarea id="reflection-text" class="reflection-area" aria-describedby="reflection-help" maxlength="1000" placeholder="Add a fictional practice note (no names or private customer details)…" ${planReviewed?'readonly':''}>${escapeHTML(reflection)}</textarea><p class="reflection-hint" id="reflection-help">Optional notes are never saved by the resume feature. Plan selections can be saved if you enable local progress. The lab does not send your answers to a server. Download or print a copy to retain notes and the plan.</p></div>${planReviewed?`<section class="feedback ${planReady()?'':'try'}" tabindex="-1" aria-label="Action plan feedback"><h2 class="feedback-heading">${planReady()?'Your plan is ready':'Refine your action plan'}</h2><p>${planReady()?'Your selections describe observable behavior, practice, a measurable criterion and a follow-up.':'Review the guidance below, then revise the highlighted choices before continuing.'}</p><div class="quality-results">${PLAN_FIELDS.map(f=>{const v=f.choices[planChoices[f.id]];return `<article class="quality-result"><h3>${escapeHTML(f.title)}</h3><p><strong>${v[2]?'✓ Workable choice':'Needs refinement'}</strong></p><p>${escapeHTML(v[1])}</p></article>`;}).join('')}</div></section>${printablePlan()}${planReady()?planButtons():''}<div class="btn-row">${button('Revise my plan','edit-plan','btn btn-secondary')}</div>`:''}<div class="btn-row split">${button('← Closing rehearsal','back','btn btn-secondary')}${planReady()?button('Next: Assessment'):`<button class="btn" data-action="review-plan" ${!planComplete()||planReviewed?'disabled':''}>Review my plan <span aria-hidden="true">→</span></button>`}</div></div>`;}
function renderAssessmentIntro(){return `<div class="scene-card">${intro('SCENE 04 · FINAL ASSESSMENT','Put Your Coaching Skills to the Test','Apply what you practiced in three new workplace situations.')}<div class="three-steps"><div class="mini-card"><b>01 · Observe</b><p>Identify a coaching opportunity using call evidence.</p></div><div class="mini-card"><b>02 · Coach</b><p>Choose a supportive coaching response.</p></div><div class="mini-card"><b>03 · Balance</b><p>Support quality while using call time purposefully.</p></div></div><div class="assessment-badges"><span>3 questions</span><span>3/3 to pass</span><span>Unlimited retries</span><span>No timer</span></div>${assessmentCastIntroduction()}<p class="notice">Practice decisions and reflection are unscored. Only these three final questions determine the result. You can revisit your choices before submitting all three. Feedback is shown after the complete attempt.</p>${nav('Begin assessment',false)}</div>`;}
const SKILL_GUIDANCE={Evidence:{title:'Evidence-based observation',practice:'Revisit the quality scorecard: compare the customer’s exact question with the Representative’s reply. Describe the omission without inferring intent.'},Adaptation:{title:'Adaptive coaching',practice:'Revisit coaching preparation and the recovery paths: explore the barrier, verify approved guidance, and rehearse a response.'},Application:{title:'Practical application',practice:'Revisit rehearsal and the action-plan builder: specify the behavior, a practice task and a measurable follow-up sample.'}};
function allAssessmentSelected(){return ASSESSMENT_QUESTIONS.every((q,i)=>Object.hasOwn(q.options,answers[i]));}
function attemptSubmitted(){return submitted.every(Boolean)&&allAssessmentSelected();}
function renderAssessment(){
  const q=ASSESSMENT_QUESTIONS[assessmentIndex], chosen=answers[assessmentIndex], last=assessmentIndex===2;
  const scenario=q.transcript?`<h2 class="section-heading">Review the customer interaction</h2>${transcript(q.transcript,true,assessmentIndex)}`:`<div class="question-card assessment-story"><p>${escapeHTML(q.scene)}</p>${q.quote?`<div class="assessment-speaker-quote">${speakerPortrait('Representative')}<blockquote class="quote">“${escapeHTML(q.quote)}”</blockquote></div>`:''}</div>`;
  return `<div class="scene-card assessment-card">${intro(`FINAL ASSESSMENT · QUESTION ${String(assessmentIndex+1).padStart(2,'0')}`,q.title,'Choose one response. Feedback is available after you submit all three questions.')}<div class="assessment-progress"><span>QUESTION ${assessmentIndex+1} OF 3</span><span class="pill">Form ${String.fromCharCode(65+(attemptNumber-1)%ASSESSMENT_BANK.length)} · Attempt ${attemptNumber}</span></div>${assessmentIndex===0?`<p class="notice"><strong>Final assessment:</strong> Three new situations · 3/3 to pass · unlimited retries · no timer. Practice is unscored. Change selections before submitting all three.</p>`:''}<nav class="assessment-jump" aria-label="Assessment questions">${ASSESSMENT_QUESTIONS.map((_,i)=>`<button type="button" class="btn btn-secondary" data-action="assessment-q${i}" ${i===assessmentIndex?'aria-current="step"':''}>Question ${i+1}${answers[i]?' · Selected':''}</button>`).join('')}</nav>${assessmentCast(assessmentIndex)}${scenario}${quizOptions(q,`assessment${assessmentIndex}`,chosen,attemptSubmitted())}<p class="notice">${last?'Review or change any response before submitting. All three selections are required.':'Your selection is retained as you move between questions.'}</p><div class="btn-row split">${assessmentIndex>0?'<button type="button" class="btn btn-secondary" data-action="assessment-previous">← Previous question</button>':''}<button class="btn" data-action="submit-assessment" type="button" ${last?!allAssessmentSelected()?'disabled':'':!chosen?'disabled':''}>${last?'Submit assessment':'Next question'} <span aria-hidden="true">→</span></button></div></div>`;
}
function resultScore(){return answers.reduce((sum,a,i)=>sum+(submitted[i]&&isCorrect(ASSESSMENT_QUESTIONS[i],a)?1:0),0)}
function renderResults(){
  if(!attemptSubmitted())return `<div class="scene-card">${intro('FINAL ASSESSMENT','Complete your attempt','Submit all three answers to receive feedback.')}${button('Return to assessment','return-assessment')}</div>`;
  const score=resultScore(),pass=score===3;
  return `<div class="scene-card ${pass?'result-success':'result-retry'}">${intro('FINAL ASSESSMENT · RESULTS',pass?'Congratulations! You Passed!':'Review Your Results',pass?'You selected the strongest response in all three scenarios.':'Review your selected responses and the recommended approaches before trying another form.')}<div class="assessment-progress"><span>FORM ${String.fromCharCode(65+(attemptNumber-1)%ASSESSMENT_BANK.length)} · ATTEMPT ${attemptNumber}</span><span class="pill">${pass?'Passed':'Not yet passed'}</span></div><div class="assessment-result-score"><div class="result-number">${score}/3</div><p>${pass?'Assessment passed':'3/3 required in one attempt'}</p></div><h2 class="section-heading">Skill breakdown</h2><div class="skill-grid">${ASSESSMENT_QUESTIONS.map((q,i)=>`<article class="mini-card"><b>${escapeHTML(SKILL_GUIDANCE[q.skill].title)}</b><p>${isCorrect(q,answers[i])?'✓ Correct':'Needs review'}</p><p>${isCorrect(q,answers[i])?'Continue applying this approach.':escapeHTML(SKILL_GUIDANCE[q.skill].practice)}</p></article>`).join('')}</div><h2 class="section-heading">${pass?'Apply your skills':'Your recommended next steps'}</h2><div class="evidence-note">${pass?'Use the coaching plan and job aid to support future practice. This simulated result is not proof of workplace performance.':ASSESSMENT_QUESTIONS.filter((q,i)=>!isCorrect(q,answers[i])).map(q=>`<p><strong>${escapeHTML(SKILL_GUIDANCE[q.skill].title)}:</strong> ${escapeHTML(SKILL_GUIDANCE[q.skill].practice)}</p>`).join('')}</div>${assessmentReview?`<section id="assessment-review" aria-label="Answer review"><h2 class="section-heading">Review your answers</h2><div class="summary-grid">${ASSESSMENT_QUESTIONS.map((q,i)=>{const v=answers[i],fb=q.feedback[v],ok=isCorrect(q,v);return `<article class="summary-row"><h3>Question ${i+1}: ${escapeHTML(q.title)} — ${ok?'Correct':'Needs review'}</h3><p class="chosen">Your choice: ${v} · Best response: ${q.correct}</p><p>${escapeHTML(q.options[v])}</p><p><strong>${escapeHTML(fb.heading)}</strong></p><p>${escapeHTML(fb.body)}</p>${ok?'':`<p><strong>Recommended response:</strong> ${escapeHTML(q.options[q.correct])}</p>`}<div class="takeaway"><strong>Takeaway:</strong> ${escapeHTML(fb.takeaway)}</div></article>`}).join('')}</div></section>`:''}<div class="btn-row split"><button class="btn btn-secondary" type="button" data-action="toggle-review" aria-expanded="${assessmentReview}">${assessmentReview?'Hide answer review':'Review answers'}</button>${pass?button('Finish lab','finish'):button('Try another form','retry')}</div><p class="image-note">${pass?'Your assessment result reflects this fictional scenario exercise.':'A different set of three questions will appear on your next attempt. Your practice and coaching plan remain intact.'}</p></div>`;
}
function renderFinish(){return `<div class="scene-card hero-layout finish-layout"><div class="hero-copy"><p class="eyebrow">QUALITY & CONVERSATIONS LAB · COMPLETE</p><h1 id="screen-title">Coaching Begins with Clarity</h1><p>You observed a call, practiced adaptive coaching, and passed all three scenario-based assessment questions.</p><div class="assessment-badges"><span>Observe evidence</span><span>Coach collaboratively</span><span>Balance quality and efficiency</span></div><a class="btn" href="coaching-guide.html" target="_blank" rel="noopener">Open coaching job aid (new tab)</a>${planReady()?planButtons():''}${button('Return to opening','restart','btn btn-secondary')}</div><div>${img('QCL_S04_Completion_Characters01_02_Celebrating.webp','Character 01, the Team Leader in an olive blouse with long dark curls, and Character 02, the blonde Representative with a bubble ponytail, celebrating their training success together at a round wooden table with an open laptop.','wide-photo completion-image')}<p class="photo-caption">This project is a portfolio demonstration. No learner results are sent to an LMS or server.</p></div>${planReady()?printablePlan():''}</div>`;}
const renderers={intro:renderIntro,review:renderReview,excerpt:renderExcerpt,scorecard:renderScorecard,observation:renderObservation,'coaching-prep':renderPrepWorkspace,'prep-barrier':renderPrep,'prep-goal':renderPrep,'prep-summary':renderPrepSummary,decision1:renderDecision1,concern:renderConcern,decision2:renderDecision2,recovery:renderRecovery,'rehearse-answer':renderRehearsal,'rehearse-close':renderRehearsal,'rehearse-summary':renderRehearsalSummary,reflection:renderReflection,'assessment-intro':renderAssessmentIntro,assessment:renderAssessment,results:renderResults,finish:renderFinish};
function render(focusFeedback=false,initialLoad=false){stage.innerHTML=renderers[step]();const path=routeSteps();const i=path.indexOf(step);$('chapter-name').textContent=chapterNames[step];const ai=path.indexOf('assessment');const n=i+(i>ai?2:i===ai?assessmentIndex:0);const count=path.length+2;$('progress-text').textContent=`Step ${n+1} of ${count}`;const percent=Math.round(n/(count-1)*100);const group=step==='intro'?-1:i<path.indexOf('coaching-prep')?0:i<path.indexOf('reflection')?1:step==='reflection'?2:3;$('stage-indicator').innerHTML=['Observe','Coach','Reflect','Assess'].map((label,j)=>`<li ${group===j&&step!=='finish'?'aria-current="step"':''} class="${j<group||step==='finish'?'done':j===group?'current':''}">${j<group||step==='finish'?'✓':j+1} <span>${label}</span></li>`).join('');$('progress-bar').style.width=percent+'%';$('course-progress').setAttribute('aria-valuenow',String(percent));$('course-progress').setAttribute('aria-valuetext',`Step ${n+1} of ${count}`);if(focusFeedback){const f=stage.querySelector(step==='scorecard'&&qualitySubmitted?'[aria-label="Quality review feedback"]':step==='coaching-prep'&&PREP_ORDER.every(k=>prepSubmitted[k])?'.prep-summary':'.feedback');if(f){f.focus();f.scrollIntoView({block:'nearest'});}}else{stage.querySelector('#screen-title')?.setAttribute('tabindex','-1');if(!initialLoad){stage.querySelector('#screen-title')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}if(!initialLoad)$('screen-announcement').textContent=focusFeedback?(document.activeElement?.querySelector('h2,h3')?.textContent||'Feedback available.'):`${chapterNames[step]}. ${stage.querySelector('h1,h2')?.textContent||''}`;persistProgress();}
function goto(next){step=next;render()}
function forward(){if(step==='intro'&&pendingSave){startFresh();return;}if(['assessment','results','finish'].includes(step))return;if(step==='excerpt'&&!evidenceSubmitted)return;if(step==='scorecard'&&(!qualitySubmitted||!evidenceSubmitted))return;if(step==='coaching-prep'&&!PREP_ORDER.every(k=>prepSubmitted[k]))return;if(step==='decision1'&&!practice.d1Submitted)return;if(step==='decision2'&&!practice.d2Submitted)return;if(step==='reflection'&&!planReady())return;if(REHEARSAL[step]&&!practice[step+'Submitted'])return;if(step==='recovery'&&recoveryData()&&!practice.recoverySubmitted)return;const path=routeSteps(),i=path.indexOf(step);if(i>=0&&i<path.length-1)goto(path[i+1]);}
function back(){const path=routeSteps(),i=path.indexOf(step);if(i>0&&step!=='results'&&step!=='finish')goto(path[i-1]);}
function resetAll(){if(!confirm('Restart the lab from the beginning? Your current answers, coaching plan and any saved progress will be cleared.'))return;pendingSave=null;savingEnabled=false;const cleared=removeSaved();syncSaveControls();storageStatus(cleared?'Saved progress cleared. Saving is off.':'Could not clear browser storage. Check your browser settings.');practice={};clearPlan();answers=[null,null,null];submitted=[false,false,false];assessmentIndex=0;attemptNumber=1;assessmentReview=false;ASSESSMENT_QUESTIONS=ASSESSMENT_BANK[0];evidence=[];evidenceSubmitted=false;qualityRatings={};qualitySubmitted=false;prepChoices={};prepSubmitted={};completedAttempt=null;goto('intro')}
function handlePractice(type){const key=type==='observation'?'observation':type==='decision1'?'d1':'d2';const choice=practice[key];if(!choice||practice[key+'Submitted'])return;practice[key+'Submitted']=true;render(true);}
function runAction(action){if(action==='submit-prep-all'){if(step==='coaching-prep'&&PREP_ORDER.every(k=>Object.hasOwn(PREPARATION[k].choices,prepChoices[k]))&&!PREP_ORDER.every(k=>prepSubmitted[k])){prepSubmitted=Object.fromEntries(PREP_ORDER.map(k=>[k,true]));render(true)}return}if(action==='review-plan'){if(step==='reflection'&&planComplete()&&!planReviewed){planReviewed=true;render(true)}return}if(action==='edit-plan'){if(step==='reflection'){planReviewed=false;render();stage.querySelector('.plan-field input:checked')?.focus()}return}if(action==='print-plan'){if(planReady())window.print();return}if(action==='download-plan'){if(planReady()){const url=URL.createObjectURL(new Blob([planText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='QCL_Coaching_Action_Plan.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}return}if(action==='submit-rehearsal'){const q=REHEARSAL[step];if(q&&Object.hasOwn(q.choices,practice[step])&&!practice[step+'Submitted']){practice[step+'Submitted']=true;render(true)}return}if(action==='retry-rehearsal'){if(REHEARSAL[step]){const start=REHEARSAL_ORDER.indexOf(step);for(const k of REHEARSAL_ORDER.slice(start)){delete practice[k];delete practice[k+'Submitted']}clearPlan();render()}return}if(action==='replay-rehearsal'){if(step==='rehearse-summary'||step==='rehearse-close'){clearRehearsal();goto('rehearse-answer')}return}if(action==='submit-recovery'){const q=recoveryData();if(step==='recovery'&&q&&Object.hasOwn(q.choices,practice.recovery)&&!practice.recoverySubmitted){practice.recoverySubmitted=true;render(true)}return}if(action==='retry-recovery'){if(step==='recovery'&&recoveryData()){clearRehearsal();delete practice.recovery;delete practice.recoverySubmitted;render()}return}if(action==='replay-coaching'){if((step==='recovery'||step==='decision2')&&confirm('Replay the coaching conversation? Your coaching decisions, rehearsal and coaching plan will be cleared; quality review and preparation will stay.')){for(const k of ['d1','d1Submitted','d2','d2Submitted','recovery','recoverySubmitted'])delete practice[k];clearRehearsal();goto('decision1')}return}if(action==='next'){forward();return}if(action==='back'){back();return}if(action==='restart'){resetAll();return}if(action==='submit-evidence'){if(step==='excerpt'&&evidence.length===2&&!evidenceSubmitted){evidenceSubmitted=true;render(true)}return}if(action==='submit-quality'){if(step==='scorecard'&&evidenceSubmitted&&qualityComplete()&&!qualitySubmitted){qualitySubmitted=true;render(true)}return}if(action==='retry-quality'){if(step==='scorecard'){qualityRatings={};qualitySubmitted=false;render()}return}if(action==='submit-prep'){if(PREPARATION[step]&&prepChoices[step]&&!prepSubmitted[step]){prepSubmitted[step]=true;render(true)}return}if(action==='retry-prep'){if(step==='prep-summary'||step==='coaching-prep'){prepChoices={};prepSubmitted={};goto('coaching-prep')}return}if(action==='submit-practice'){handlePractice(step);return}if(action==='return-assessment'&&step==='results'&&!attemptSubmitted()){goto('assessment');return}if(step==='assessment'&&!attemptSubmitted()&&/^assessment-q[0-2]$/.test(action)){assessmentIndex=Number(action.slice(-1));render();return}if(action==='assessment-previous'){if(step==='assessment'&&!attemptSubmitted()&&assessmentIndex>0){assessmentIndex--;render()}return}if(action==='submit-assessment'){if(step!=='assessment'||attemptSubmitted()||!Object.hasOwn(ASSESSMENT_QUESTIONS[assessmentIndex].options,answers[assessmentIndex]))return;if(assessmentIndex<2){assessmentIndex++;render();return}if(!allAssessmentSelected())return;submitted=[true,true,true];completedAttempt={attemptNumber,answers:[...answers]};assessmentReview=true;goto('results');return}if(action==='toggle-review'&&step==='results'&&attemptSubmitted()){assessmentReview=!assessmentReview;render();stage.querySelector('[data-action="toggle-review"]')?.focus();return}if(action==='retry'&&step==='results'&&attemptSubmitted()&&resultScore()<3){completedAttempt=null;answers=[null,null,null];submitted=[false,false,false];assessmentIndex=0;attemptNumber++;ASSESSMENT_QUESTIONS=ASSESSMENT_BANK[(attemptNumber-1)%ASSESSMENT_BANK.length];assessmentReview=false;goto('assessment');return}if(action==='finish'&&step==='results'&&attemptSubmitted()&&resultScore()===3){goto('finish')}}

// Lesson 04B — local, opt-in progress. No personal data or free-text notes are saved.
const SAVE_KEY='qcl-professional-v3-progress-04b';
const SAVE_VERSION=1;
let savingEnabled=false,pendingSave=null,storageProblem=false;
const isRecord=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const validChoice=x=>typeof x==='string'&&['A','B','C'].includes(x);
function structuredState(){return {version:SAVE_VERSION,step,practice:{...practice},planChoices:{...planChoices},planReviewed,answers:[...answers],assessmentIndex,submitted:[...submitted],assessmentReview,attemptNumber,evidence:[...evidence],evidenceSubmitted,qualityRatings:{...qualityRatings},qualitySubmitted,prepChoices:{...prepChoices},prepSubmitted:{...prepSubmitted}};}
function validateSnapshot(d){
  if(!isRecord(d)||d.version!==SAVE_VERSION||!steps.includes(d.step)||d.step==='intro')return null;
  if(!Number.isSafeInteger(d.attemptNumber)||d.attemptNumber<1||!Number.isInteger(d.assessmentIndex)||d.assessmentIndex<0||d.assessmentIndex>2)return null;
  const bools=['planReviewed','assessmentReview','evidenceSubmitted','qualitySubmitted'];if(bools.some(k=>typeof d[k]!=='boolean'))return null;
  const maps=['practice','planChoices','qualityRatings','prepChoices','prepSubmitted'];if(maps.some(k=>!isRecord(d[k])))return null;
  if(!Array.isArray(d.evidence)||d.evidence.length>2||new Set(d.evidence).size!==d.evidence.length||d.evidence.some(x=>![0,1,2].includes(x)))return null;
  if(!Array.isArray(d.answers)||d.answers.length!==3||d.answers.some(x=>x!==null&&!validChoice(x)))return null;
  if(!Array.isArray(d.submitted)||d.submitted.length!==3||d.submitted.some(x=>typeof x!=='boolean')||d.submitted.some(x=>x!==d.submitted[0]))return null;
  const copy={version:SAVE_VERSION,step:d.step,practice:{},planChoices:{},planReviewed:d.planReviewed,answers:[...d.answers],assessmentIndex:d.assessmentIndex,submitted:[...d.submitted],assessmentReview:d.assessmentReview,attemptNumber:d.attemptNumber,evidence:[...d.evidence],evidenceSubmitted:d.evidenceSubmitted,qualityRatings:{},qualitySubmitted:d.qualitySubmitted,prepChoices:{},prepSubmitted:{}};
  for(const k of ['d1','d2','recovery',...REHEARSAL_ORDER]){if(Object.hasOwn(d.practice,k)){if(!validChoice(d.practice[k]))return null;copy.practice[k]=d.practice[k];}if(Object.hasOwn(d.practice,k+'Submitted')){if(typeof d.practice[k+'Submitted']!=='boolean'||(d.practice[k+'Submitted']&&!copy.practice[k]))return null;copy.practice[k+'Submitted']=d.practice[k+'Submitted'];}}
  for(const c of QUALITY_CRITERIA){if(Object.hasOwn(d.qualityRatings,c.id)){if(!Object.hasOwn(QUALITY_STATES,d.qualityRatings[c.id]))return null;copy.qualityRatings[c.id]=d.qualityRatings[c.id];}}
  for(const k of PREP_ORDER){if(Object.hasOwn(d.prepChoices,k)){if(!Object.hasOwn(PREPARATION[k].choices,d.prepChoices[k]))return null;copy.prepChoices[k]=d.prepChoices[k];}if(Object.hasOwn(d.prepSubmitted,k)){if(typeof d.prepSubmitted[k]!=='boolean'||(d.prepSubmitted[k]&&!copy.prepChoices[k]))return null;copy.prepSubmitted[k]=d.prepSubmitted[k];}}
  for(const f of PLAN_FIELDS){if(Object.hasOwn(d.planChoices,f.id)){if(!Object.hasOwn(f.choices,d.planChoices[f.id]))return null;copy.planChoices[f.id]=d.planChoices[f.id];}}
  const after=k=>steps.indexOf(d.step)>steps.indexOf(k);
  const p=copy.practice,prepDone=PREP_ORDER.every(k=>copy.prepSubmitted[k]);
  if(d.evidenceSubmitted&&copy.evidence.length!==2)return null;
  // Migrate unfinished saves from the earlier combined scorecard without discarding selections.
  if(d.step==='scorecard'&&!d.evidenceSubmitted)copy.step='excerpt';
  if(d.qualitySubmitted&&(!d.evidenceSubmitted||!QUALITY_CRITERIA.every(c=>Object.hasOwn(copy.qualityRatings,c.id))))return null;
  if(after('scorecard')&&!d.qualitySubmitted||after('coaching-prep')&&!prepDone||after('decision1')&&!p.d1Submitted||after('decision2')&&!p.d2Submitted)return null;
  const outcome=OUTCOMES[(p.d1||'A')+(p.d2||'B')];
  if(d.step==='recovery'&&(!p.d2Submitted||!outcome?.repair)||after('recovery')&&outcome?.repair&&!p.recoverySubmitted)return null;
  if(after('rehearse-answer')&&!p['rehearse-answerSubmitted']||after('rehearse-close')&&!p['rehearse-closeSubmitted'])return null;
  if(d.planReviewed&&!PLAN_FIELDS.every(f=>Object.hasOwn(copy.planChoices,f.id)))return null;
  if(after('reflection')&&(!d.planReviewed||!PLAN_FIELDS.every(f=>f.choices[copy.planChoices[f.id]]?.[2])))return null;
  if(d.submitted[0]&&!d.answers.every(validChoice))return null;
  if(['results','finish'].includes(d.step)!==d.submitted[0])return null;
  if(d.step==='finish'&&!ASSESSMENT_BANK[(d.attemptNumber-1)%ASSESSMENT_BANK.length].every((q,i)=>isCorrect(q,d.answers[i])))return null;
  return copy;
}
function storageStatus(message){if($('save-status').textContent!==message)$('save-status').textContent=message;}
function syncSaveControls(){
  $('save-progress').checked=savingEnabled;$('save-progress').disabled=!!pendingSave;$('save-toggle-label').hidden=!!pendingSave;
  $('saved-session').hidden=!pendingSave;$('clear-progress').hidden=!savingEnabled&&!pendingSave&&!storageProblem;
  if(pendingSave)$('saved-location').textContent=`Saved location: ${chapterNames[pendingSave.step]}${pendingSave.step==='assessment'?' · Question '+(pendingSave.assessmentIndex+1):''}.`;
}
function removeSaved(){try{window.localStorage.removeItem(SAVE_KEY);storageProblem=false;return true;}catch{storageProblem=true;return false;}}
function persistProgress(){if(!savingEnabled||pendingSave)return;try{if(step==='intro'){storageStatus('Saving is on. Progress will be saved when you begin.');return;}const snapshot=validateSnapshot(structuredState());if(!snapshot){storageStatus('Progress could not be saved at this point.');return;}window.localStorage.setItem(SAVE_KEY,JSON.stringify(snapshot));storageProblem=false;storageStatus('Progress saved on this browser.');}catch{savingEnabled=false;storageProblem=true;storageStatus('Browser storage is unavailable. Continue without saving.');}syncSaveControls();}
function loadSaved(){try{const raw=window.localStorage.getItem(SAVE_KEY);if(!raw)return;const parsed=validateSnapshot(JSON.parse(raw));if(parsed){pendingSave=parsed;storageStatus('Saved progress found. Resume or start a new session.');}else{removeSaved();storageStatus('An incompatible or incomplete save was cleared. Start a new session.');}}catch{removeSaved();storageStatus('Saved progress could not be read. You can still complete the lab.');}syncSaveControls();}
function resumeSaved(){if(!pendingSave)return;const d=pendingSave;pendingSave=null;savingEnabled=true;step=d.step;practice=d.practice;planChoices=d.planChoices;planReviewed=d.planReviewed;reflection='';answers=d.answers;assessmentIndex=d.assessmentIndex;submitted=d.submitted;assessmentReview=d.assessmentReview;attemptNumber=d.attemptNumber;ASSESSMENT_QUESTIONS=ASSESSMENT_BANK[(attemptNumber-1)%ASSESSMENT_BANK.length];completedAttempt=submitted.every(Boolean)?{attemptNumber,answers:[...answers]}:null;evidence=d.evidence;evidenceSubmitted=d.evidenceSubmitted;qualityRatings=d.qualityRatings;qualitySubmitted=d.qualitySubmitted;prepChoices=d.prepChoices;prepSubmitted=d.prepSubmitted;syncSaveControls();render();}
function clearSavedProgress(){if(!confirm('Delete saved progress from this browser and turn off saving? The current open session will remain.'))return;pendingSave=null;savingEnabled=false;const ok=removeSaved();syncSaveControls();if(step==='intro')render();storageStatus(ok?'Saved progress cleared. Saving is off.':'Could not clear browser storage. Check your browser’s site-data settings.');$('save-progress').focus();}
function startFresh(){if(!pendingSave)return;if(!confirm('Start a new session and delete saved progress?'))return;pendingSave=null;savingEnabled=false;const ok=removeSaved();syncSaveControls();storageStatus(ok?'Saved progress cleared. Saving is off.':'Could not clear saved progress. Check browser settings.');goto('excerpt');}

stage.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(btn&&!btn.disabled)runAction(btn.dataset.action)});
stage.addEventListener('change',e=>{if(e.target.matches('input[name="evidence"]')){const n=Number(e.target.value);if(e.target.checked){if(evidence.length===2){e.target.checked=false;$('screen-announcement').textContent='Two statements already selected. Uncheck one before choosing another.';return}evidence.push(n)}else{evidence=evidence.filter(x=>x!==n)}stage.querySelector('[data-action="submit-evidence"]').disabled=evidence.length!==2;return}if(!e.target.matches('input[type="radio"]'))return;const val=e.target.value;const name=e.target.name;if(name.startsWith('plan-')){const f=PLAN_FIELDS.find(x=>x.id===name.slice(5));if(step==='reflection'&&!planReviewed&&f&&Object.hasOwn(f.choices,val)){planChoices[f.id]=val;const b=stage.querySelector('[data-action=review-plan]');if(b)b.disabled=!planComplete()}return}if(name==='rehearsal-choice'){if(REHEARSAL[step]&&!practice[step+'Submitted']&&Object.hasOwn(REHEARSAL[step].choices,val)){practice[step]=val;const b=stage.querySelector('[data-action=submit-rehearsal]');if(b)b.disabled=false}return}if(name.startsWith('quality-')){if(!qualitySubmitted&&Object.hasOwn(QUALITY_STATES,val)){qualityRatings[name.slice(8)]=val;const b=stage.querySelector('[data-action="submit-quality"]');if(b)b.disabled=!qualityComplete()||!evidenceSubmitted}return}if(name.startsWith('prep-')&&name!=='prep-choice'){const k=name.slice(5);if(step==='coaching-prep'&&PREPARATION[k]&&!prepSubmitted[k]&&Object.hasOwn(PREPARATION[k].choices,val)){prepChoices[k]=val;const b=stage.querySelector('[data-action=submit-prep-all]');if(b)b.disabled=!PREP_ORDER.every(x=>Object.hasOwn(PREPARATION[x].choices,prepChoices[x]))}return}if(name==='prep-choice'){if(!prepSubmitted[step]&&PREPARATION[step]){prepChoices[step]=val;const b=stage.querySelector('[data-action="submit-prep"]');if(b)b.disabled=false}return}if(name==='recovery'){if(step==='recovery'&&!practice.recoverySubmitted){practice.recovery=val;const b=stage.querySelector('[data-action=submit-recovery]');if(b)b.disabled=false}return}if(name==='obs'){practice.observation=val}else if(name==='d1'){practice.d1=val}else if(name==='d2'){practice.d2=val}else if(name===`assessment${assessmentIndex}`&&step==='assessment'&&!attemptSubmitted()&&Object.hasOwn(ASSESSMENT_QUESTIONS[assessmentIndex].options,val)){answers[assessmentIndex]=val;const b=stage.querySelector('[data-action=submit-assessment]');if(b)b.disabled=assessmentIndex===2&&!allAssessmentSelected();const jump=stage.querySelector(`[data-action=assessment-q${assessmentIndex}]`);if(jump)jump.textContent=`Question ${assessmentIndex+1} · Selected`;return}const submit=stage.querySelector('[data-action="submit-assessment"], [data-action="submit-practice"]');if(submit)submit.disabled=false});
stage.addEventListener('input',e=>{if(e.target.id==='reflection-text'&&!planReviewed){reflection=e.target.value.slice(0,1000)}});

stage.addEventListener('change',persistProgress);
$('save-progress').addEventListener('change',e=>{if(e.target.checked){savingEnabled=true;try{window.localStorage.setItem(SAVE_KEY+'-probe','1');window.localStorage.removeItem(SAVE_KEY+'-probe');storageProblem=false;persistProgress();}catch{savingEnabled=false;storageProblem=true;storageStatus('Browser storage is unavailable. Continue without saving.');}}else{savingEnabled=false;const ok=removeSaved();storageStatus(ok?'Saving is off. Stored progress was deleted.':'Unable to delete stored progress. Check browser settings.');}syncSaveControls();});
$('resume-course').addEventListener('click',resumeSaved);
$('start-fresh').addEventListener('click',startFresh);
$('clear-progress').addEventListener('click',clearSavedProgress);
$('restart-course').addEventListener('click',resetAll);
$('home-link').addEventListener('click',e=>{e.preventDefault();resetAll()});
loadSaved();
syncSaveControls();
